CREATE OR ALTER PROCEDURE [dbo].[uspIngredient_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @PurchaseUomId UNIQUEIDENTIFIER = NULL
	, @IssueUomId UNIQUEIDENTIFIER = NULL
	, @StorageType NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @CompanyId UNIQUEIDENTIFIER = NULL
	, @IngredientCategoryId UNIQUEIDENTIFIER = NULL
	, @BaseUnitId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[Code]
			, t.[Name]
			, t.[PurchaseUomId]
			, t.[IssueUomId]
			, t.[StorageType]
			, t.[ShelfLifeDays]
			, t.[YieldPercent]
			, t.[StandardWastePercent]
			, t.[LotControl]
			, t.[ExpiryControl]
			, t.[QcRequired]
			, t.[Status]
			, t.[Note]
			, t.[CompanyId]
			, j1.[Name] AS [CompanyName]
			, t.[IngredientCategoryId]
			, j2.[Name] AS [IngredientCategoryName]
			, t.[BaseUnitId]
			, j3.[Name] AS [BaseUnitName]
			, t.[Specification]
			, t.[StorageCondition]
			, t.[IsExpiryManaged]
			, t.[MinimumStock]
			, t.[SafetyStock]
			, t.[CreatedDate]
		FROM [dbo].[Ingredient] AS t
		LEFT JOIN [dbo].[Company] AS j1 ON j1.[Id] = t.[CompanyId]
		LEFT JOIN [dbo].[IngredientCategorie] AS j2 ON j2.[Id] = t.[IngredientCategoryId]
		LEFT JOIN [dbo].[UnitMeasure] AS j3 ON j3.[Id] = t.[BaseUnitId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%'))
			AND (@PurchaseUomId IS NULL OR t.[PurchaseUomId] = @PurchaseUomId)
			AND (@IssueUomId IS NULL OR t.[IssueUomId] = @IssueUomId)
			AND (ISNULL(@StorageType, '') = '' OR t.[StorageType] = @StorageType)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@CompanyId IS NULL OR t.[CompanyId] = @CompanyId)
			AND (@IngredientCategoryId IS NULL OR t.[IngredientCategoryId] = @IngredientCategoryId)
			AND (@BaseUnitId IS NULL OR t.[BaseUnitId] = @BaseUnitId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'purchaseUomId' THEN r.[PurchaseUomId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'purchaseUomId' THEN r.[PurchaseUomId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'issueUomId' THEN r.[IssueUomId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'issueUomId' THEN r.[IssueUomId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'storageType' THEN r.[StorageType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'storageType' THEN r.[StorageType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shelfLifeDays' THEN r.[ShelfLifeDays] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shelfLifeDays' THEN r.[ShelfLifeDays] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'yieldPercent' THEN r.[YieldPercent] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'yieldPercent' THEN r.[YieldPercent] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'standardWastePercent' THEN r.[StandardWastePercent] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'standardWastePercent' THEN r.[StandardWastePercent] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lotControl' THEN r.[LotControl] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lotControl' THEN r.[LotControl] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'expiryControl' THEN r.[ExpiryControl] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'expiryControl' THEN r.[ExpiryControl] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'qcRequired' THEN r.[QcRequired] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'qcRequired' THEN r.[QcRequired] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'companyId' THEN r.[CompanyId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'companyId' THEN r.[CompanyId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'companyName' THEN r.[CompanyName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'companyName' THEN r.[CompanyName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientCategoryId' THEN r.[IngredientCategoryId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientCategoryId' THEN r.[IngredientCategoryId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientCategoryName' THEN r.[IngredientCategoryName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientCategoryName' THEN r.[IngredientCategoryName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'baseUnitId' THEN r.[BaseUnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'baseUnitId' THEN r.[BaseUnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'baseUnitName' THEN r.[BaseUnitName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'baseUnitName' THEN r.[BaseUnitName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'specification' THEN r.[Specification] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'specification' THEN r.[Specification] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'storageCondition' THEN r.[StorageCondition] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'storageCondition' THEN r.[StorageCondition] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isExpiryManaged' THEN r.[IsExpiryManaged] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isExpiryManaged' THEN r.[IsExpiryManaged] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'minimumStock' THEN r.[MinimumStock] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'minimumStock' THEN r.[MinimumStock] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'safetyStock' THEN r.[SafetyStock] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'safetyStock' THEN r.[SafetyStock] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
